export const envelope = [56, 44, 56];

export default function build(api) {
  const [W, H, D] = api.size;
  const grid = new Array(W * H * D);

  // --- Palette Definitions ---
  const DARK_PRIS = "minecraft:dark_prismarine";
  const PRIS_BRICK = "minecraft:prismarine_bricks";
  const PRIS = "minecraft:prismarine";
  const SEA_LANTERN = "minecraft:sea_lantern";
  const CRYING_OBS = "minecraft:crying_obsidian";
  const FROG_VERDANT = "minecraft:verdant_froglight";
  const FROG_OCHRE = "minecraft:ochre_froglight";
  const BONE_Y = "minecraft:bone_block[axis=y]";
  const BONE_Z = "minecraft:bone_block[axis=z]";
  const MAGMA = "minecraft:magma_block";
  const SCULK = "minecraft:sculk";

  // World Theme: Hellenist Harbor Waterfront
  const stonePri = api.theme.stone.primary || "minecraft:quartz_block";
  const stoneAcc = api.theme.stone.accent || "minecraft:smooth_stone";
  const stoneStairs = api.theme.stone.stairs || "minecraft:quartz_stairs";
  const stoneSlab = api.theme.stone.slab || "minecraft:quartz_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:diorite_wall";
  const groundPave = api.theme.ground.pavement || "minecraft:smooth_stone";
  const woodLog = api.theme.wood.log || "minecraft:dark_oak_log";
  const woodPlank = api.theme.wood.planks || "minecraft:dark_oak_planks";
  const woodFence = api.theme.wood.fence || "minecraft:dark_oak_fence";

  // --- Grid Voxel Helpers ---
  function setV(x, y, z, block) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[(x * H + y) * D + z] = block;
    }
  }

  function getV(x, y, z) {
    x = Math.round(x);
    y = Math.round(y);
    z = Math.round(z);
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[(x * H + y) * D + z];
    }
    return undefined;
  }

  // --- Geometric Drawing Primitives ---
  function drawSphere(cx, cy, cz, r, matFn) {
    const rCeil = Math.ceil(r);
    const r2 = r * r;
    const minX = Math.max(0, Math.floor(cx - rCeil));
    const maxX = Math.min(W - 1, Math.ceil(cx + rCeil));
    const minY = Math.max(0, Math.floor(cy - rCeil));
    const maxY = Math.min(H - 1, Math.ceil(cy + rCeil));
    const minZ = Math.max(0, Math.floor(cz - rCeil));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rCeil));

    for (let x = minX; x <= maxX; x++) {
      const dx = x - cx;
      const dx2 = dx * dx;
      for (let y = minY; y <= maxY; y++) {
        const dy = y - cy;
        const dy2 = dy * dy;
        for (let z = minZ; z <= maxZ; z++) {
          const dz = z - cz;
          const d2 = dx2 + dy2 + dz * dz;
          if (d2 <= r2) {
            const block = matFn(x, y, z, dx, dy, dz, Math.sqrt(d2) / r);
            if (block) {
              grid[(x * H + y) * D + z] = block;
            }
          }
        }
      }
    }
  }

  function getBezierPoint(pts, t) {
    let current = pts;
    while (current.length > 1) {
      const next = [];
      for (let i = 0; i < current.length - 1; i++) {
        next.push([
          current[i][0] + (current[i + 1][0] - current[i][0]) * t,
          current[i][1] + (current[i + 1][1] - current[i][1]) * t,
          current[i][2] + (current[i + 1][2] - current[i][2]) * t,
        ]);
      }
      current = next;
    }
    return current[0];
  }

  function drawSpline(pts, rStart, rEnd, matGen, numSteps = 70) {
    for (let i = 0; i <= numSteps; i++) {
      const t = i / numSteps;
      const pt = getBezierPoint(pts, t);
      const r = rStart + (rEnd - rStart) * t;
      const matFn = matGen(t, pt);
      drawSphere(pt[0], pt[1], pt[2], r, matFn);
    }
  }

  // --- Material Generators for Leviathan Anatomy ---
  function bodyMatGen(t, centerPt) {
    return function (x, y, z, dx, dy, dz, normDist) {
      // Lateral glowing stripes
      const isLateral = Math.abs(dx) > 3.0 && Math.abs(dy) < 2.5 && (Math.floor(z + t * 8) % 3 === 0);
      if (isLateral && normDist > 0.6) return SEA_LANTERN;

      // Dorsal carapace
      if (dy > 0.4) {
        if (normDist > 0.8 && (x + y + z) % 6 === 0) return CRYING_OBS;
        if (normDist > 0.85 && (x * z) % 7 === 0) return SCULK;
        return DARK_PRIS;
      }
      // Ventral underbelly
      if (dy < -0.4) {
        return (x + z) % 2 === 0 ? PRIS_BRICK : PRIS;
      }
      // Lateral flanks
      if (normDist > 0.75 && (y + z) % 4 === 0) return SEA_LANTERN;
      return PRIS;
    };
  }

  function tentacleMatGen(t, centerPt, normalDir) {
    const len = Math.hypot(normalDir[0], normalDir[1], normalDir[2]) || 1;
    const nx = normalDir[0] / len;
    const ny = normalDir[1] / len;
    const nz = normalDir[2] / len;

    return function (x, y, z, dx, dy, dz, normDist) {
      const dot = dx * nx + dy * ny + dz * nz;
      // Inward ventral sucker row
      if (dot > 0.35 && normDist > 0.65) {
        if (dot > 0.75) {
          return Math.floor(t * 32) % 2 === 0 ? FROG_OCHRE : BONE_Y;
        }
        return DARK_PRIS;
      }
      // Bioluminescent lateral bead
      if (Math.abs(dot) < 0.25 && normDist > 0.75 && Math.floor(t * 22) % 3 === 0) {
        return SEA_LANTERN;
      }
      // Dorsal tentacle skin
      if (dot < -0.3) {
        return DARK_PRIS;
      }
      return PRIS_BRICK;
    };
  }

  // ==========================================
  // 1. LEVIATHAN MAIN BODY & HEAD
  // ==========================================

  // Massive breaching torso curving upward and forward
  const bodySpine = [
    [28, 0, 42],
    [28, 8, 34],
    [28, 17, 26],
    [28, 25, 18],
  ];
  drawSpline(bodySpine, 9.2, 7.0, bodyMatGen, 50);

  // Upper Cranium & Snout
  const upperJawSpine = [
    [28, 25, 18],
    [28, 30, 14],
    [28, 29, 8],
    [28, 27, 4],
  ];
  drawSpline(
    upperJawSpine,
    6.2,
    2.6,
    (t) => (x, y, z, dx, dy, dz, normDist) => {
      if (dy > 0.3) return normDist > 0.75 ? DARK_PRIS : PRIS;
      if (normDist > 0.8) return CRYING_OBS;
      return PRIS_BRICK;
    },
    40
  );

  // Lower Jaw
  const lowerJawSpine = [
    [28, 20, 18],
    [28, 16, 14],
    [28, 15, 9],
    [28, 17, 6],
  ];
  drawSpline(
    lowerJawSpine,
    4.5,
    2.2,
    (t) => (x, y, z, dx, dy, dz, normDist) => {
      if (dy < -0.2) return PRIS_BRICK;
      return PRIS;
    },
    30
  );

  // Deep Maw Void & Molten Gullet
  for (let x = 25; x <= 31; x++) {
    for (let y = 19; y <= 26; y++) {
      for (let z = 14; z <= 18; z++) {
        const dx = (x - 28) / 3;
        const dy = (y - 22.5) / 3.5;
        const dz = (z - 16) / 2;
        if (dx * dx + dy * dy + dz * dz <= 1.0) {
          setV(x, y, z, z >= 16 ? MAGMA : FROG_VERDANT);
        }
      }
    }
  }

  // Upper Teeth / Fangs (pointing downward)
  for (let z = 6; z <= 14; z++) {
    for (let x = 24; x <= 32; x++) {
      const isRim = Math.abs(x - 28) >= 2.5 || z <= 7;
      if (isRim && getV(x, 27, z) && !getV(x, 26, z)) {
        setV(x, 26, z, BONE_Y);
        if (z <= 9 && !getV(x, 25, z)) setV(x, 25, z, BONE_Y);
      }
    }
  }

  // Lower Teeth / Fangs (pointing upward)
  for (let z = 7; z <= 14; z++) {
    for (let x = 24; x <= 32; x++) {
      const isRim = Math.abs(x - 28) >= 2.2 || z <= 8;
      if (isRim && getV(x, 17, z) && !getV(x, 18, z)) {
        setV(x, 18, z, BONE_Y);
        if (z <= 10 && !getV(x, 19, z)) setV(x, 19, z, BONE_Y);
      }
    }
  }

  // Bioluminescent Predatory Compound Eyes
  const eyes = [
    { cx: 22, cy: 28, cz: 11 },
    { cx: 34, cy: 28, cz: 11 },
  ];
  for (const eye of eyes) {
    setV(eye.cx, eye.cy, eye.cz, FROG_VERDANT);
    setV(eye.cx, eye.cy, eye.cz - 1, SEA_LANTERN);
    setV(eye.cx, eye.cy + 1, eye.cz, CRYING_OBS);
    setV(eye.cx, eye.cy - 1, eye.cz, CRYING_OBS);
    setV(eye.cx + (eye.cx < 28 ? -1 : 1), eye.cy, eye.cz, DARK_PRIS);
    setV(eye.cx, eye.cy, eye.cz + 1, CRYING_OBS);
    // Heavy brow ridge
    setV(eye.cx, eye.cy + 2, eye.cz, DARK_PRIS);
    setV(eye.cx, eye.cy + 2, eye.cz - 1, DARK_PRIS);
  }

  // Dorsal Spines & Crest Sails along the back
  const dorsalCrests = [
    { zMin: 13, zMax: 20, zPeak: 16, hMax: 8 },
    { zMin: 22, zMax: 30, zPeak: 26, hMax: 7 },
    { zMin: 32, zMax: 40, zPeak: 36, hMax: 6 },
  ];
  for (const crest of dorsalCrests) {
    for (let z = crest.zMin; z <= crest.zMax; z++) {
      const t = 1 - Math.abs(z - crest.zPeak) / (crest.zMax - crest.zMin);
      const finHeight = Math.round(crest.hMax * Math.max(0, t));
      let topY = 0;
      for (let y = H - 1; y >= 0; y--) {
        if (getV(28, y, z)) {
          topY = y;
          break;
        }
      }
      if (topY > 0) {
        for (let dy = 1; dy <= finHeight; dy++) {
          const y = topY + dy;
          if (y < H) {
            if (dy === finHeight) setV(28, y, z, SEA_LANTERN);
            else if (dy >= finHeight - 1) setV(28, y, z, CRYING_OBS);
            else setV(28, y, z, DARK_PRIS);
          }
        }
      }
    }
  }

  // Cranial Horns sweeping backward
  const leftHorn = [
    [24, 31, 14],
    [19, 37, 20],
    [15, 41, 26],
  ];
  drawSpline(leftHorn, 2.0, 0.7, () => () => DARK_PRIS, 25);
  const rightHorn = [
    [32, 31, 14],
    [37, 37, 20],
    [41, 41, 26],
  ];
  drawSpline(rightHorn, 2.0, 0.7, () => () => DARK_PRIS, 25);

  // Pectoral Fin Scythes
  const leftPectoral = [
    [19, 14, 24],
    [11, 16, 28],
    [5, 18, 34],
    [2, 14, 39],
  ];
  drawSpline(leftPectoral, 2.5, 0.8, () => () => DARK_PRIS, 30);
  const rightPectoral = [
    [37, 14, 24],
    [45, 16, 28],
    [51, 18, 34],
    [54, 14, 39],
  ];
  drawSpline(rightPectoral, 2.5, 0.8, () => () => DARK_PRIS, 30);

  // ==========================================
  // 2. EIGHT GARTH-SPANNING TENTACLES
  // ==========================================

  // Tentacle 1: Front-Left Harbor Crusher (smashes into pier)
  const t1Pts = [
    [22, 6, 22],
    [14, 18, 16],
    [9, 32, 10],
    [12, 22, 4],
    [15, 6, 3],
    [17, 4, 2],
  ];
  drawSpline(t1Pts, 4.0, 1.8, (t) => tentacleMatGen(t, null, [1, -0.5, 0.5]), 55);

  // Tentacle 2: Front-Right Colonnade Smasher (wraps column)
  const t2Pts = [
    [34, 6, 22],
    [42, 18, 16],
    [47, 32, 10],
    [44, 22, 4],
    [40, 6, 3],
    [39, 4, 2],
  ];
  drawSpline(t2Pts, 4.0, 1.8, (t) => tentacleMatGen(t, null, [-1, -0.5, 0.5]), 55);

  // Tentacle 3: Left High Sky Whip
  const t3Pts = [
    [20, 4, 30],
    [10, 15, 28],
    [4, 28, 20],
    [6, 40, 14],
    [12, 38, 10],
  ];
  drawSpline(t3Pts, 3.8, 1.4, (t) => tentacleMatGen(t, null, [0.8, -0.5, -0.3]), 50);

  // Tentacle 4: Right High Sky Whip
  const t4Pts = [
    [36, 4, 30],
    [46, 15, 28],
    [52, 28, 20],
    [50, 40, 14],
    [44, 38, 10],
  ];
  drawSpline(t4Pts, 3.8, 1.4, (t) => tentacleMatGen(t, null, [-0.8, -0.5, -0.3]), 50);

  // Tentacle 5: Left Flank Sweeper
  const t5Pts = [
    [21, 3, 38],
    [10, 12, 42],
    [4, 23, 38],
    [6, 31, 30],
    [12, 30, 25],
  ];
  drawSpline(t5Pts, 3.5, 1.3, (t) => tentacleMatGen(t, null, [0.7, -0.2, -0.7]), 45);

  // Tentacle 6: Right Flank Sweeper
  const t6Pts = [
    [35, 3, 38],
    [46, 12, 42],
    [52, 23, 38],
    [50, 31, 30],
    [44, 30, 25],
  ];
  drawSpline(t6Pts, 3.5, 1.3, (t) => tentacleMatGen(t, null, [-0.7, -0.2, -0.7]), 45);

  // Tentacle 7: Rear High Left Thrash
  const t7Pts = [
    [24, 2, 44],
    [18, 14, 49],
    [17, 28, 50],
    [21, 37, 45],
    [25, 34, 39],
  ];
  drawSpline(t7Pts, 3.6, 1.4, (t) => tentacleMatGen(t, null, [0.5, -0.5, -0.7]), 45);

  // Tentacle 8: Rear High Right Thrash
  const t8Pts = [
    [32, 2, 44],
    [38, 14, 49],
    [39, 28, 50],
    [35, 37, 45],
    [31, 34, 39],
  ];
  drawSpline(t8Pts, 3.6, 1.4, (t) => tentacleMatGen(t, null, [-0.5, -0.5, -0.7]), 45);

  // ==========================================
  // 3. HELLENIST HARBOR QUAY WATERFRONT (Z=0..8)
  // ==========================================

  // Left Quayside Promenade (X = 4..20, Z = 1..7)
  for (let x = 4; x <= 20; x++) {
    for (let z = 1; z <= 7; z++) {
      // Solid plinth foundation
      for (let y = 1; y <= 5; y++) {
        setV(x, y, z, stonePri);
      }
      // Promenade paved surface
      const isBorder = x === 4 || z === 1 || z === 7;
      setV(x, 6, z, isBorder ? stoneAcc : groundPave);
    }
  }

  // Right Quayside Promenade (X = 36..52, Z = 1..7)
  for (let x = 36; x <= 52; x++) {
    for (let z = 1; z <= 7; z++) {
      for (let y = 1; y <= 5; y++) {
        setV(x, y, z, stonePri);
      }
      const isBorder = x === 52 || z === 1 || z === 7;
      setV(x, 6, z, isBorder ? stoneAcc : groundPave);
    }
  }

  // Central Shattered Quay Zone (X = 21..35, Z = 1..8)
  for (let x = 21; x <= 35; x++) {
    const distCenter = Math.abs(x - 28);
    const breachY = Math.max(1, Math.min(5, Math.floor(distCenter * 0.8)));
    for (let z = 1; z <= 6; z++) {
      for (let y = 1; y <= breachY; y++) {
        if (!getV(x, y, z)) {
          setV(x, y, z, stonePri);
        }
      }
      // Shattered masonry debris
      if (breachY >= 2 && (x + z) % 3 === 0 && !getV(x, breachY + 1, z)) {
        setV(x, breachY + 1, z, (x + z) % 2 === 0 ? stoneStairs : stoneSlab);
      }
    }
  }

  // Classical Balustrades along Quayside
  for (let x = 4; x <= 12; x++) {
    setV(x, 7, 7, stoneWall);
    setV(x, 8, 7, stoneSlab);
  }
  for (let x = 44; x <= 52; x++) {
    setV(x, 7, 7, stoneWall);
    setV(x, 8, 7, stoneSlab);
  }

  // Classical Monumental Columns on the Promenade
  // Column 1: Intact Left Beacon Colonnade (X=8..9, Z=3..4)
  for (let cx = 8; cx <= 9; cx++) {
    for (let cz = 3; cz <= 4; cz++) {
      for (let y = 6; y <= 12; y++) {
        setV(cx, y, cz, stonePri);
      }
      setV(cx, 13, cz, stoneStairs);
    }
  }
  // Harbor beacon on top
  setV(8, 14, 3, stoneWall);
  setV(8, 15, 3, SEA_LANTERN);

  // Column 2: Shattered by Tentacle 1 (X=15..16, Z=3..4)
  for (let cx = 15; cx <= 16; cx++) {
    for (let cz = 3; cz <= 4; cz++) {
      setV(cx, 6, cz, stonePri);
      setV(cx, 7, cz, stonePri);
      setV(cx, 8, cz, stonePri);
    }
  }
  // Toppled column chunks on quay
  setV(17, 6, 2, stonePri);
  setV(18, 6, 3, stonePri);
  setV(18, 7, 3, stoneStairs);
  setV(19, 6, 4, stoneSlab);

  // Column 3: Gripped & Wrapped by Tentacle 2 (X=41..42, Z=3..4)
  for (let cx = 41; cx <= 42; cx++) {
    for (let cz = 3; cz <= 4; cz++) {
      for (let y = 6; y <= 13; y++) {
        if (!getV(cx, y, cz)) {
          setV(cx, y, cz, stonePri);
        }
      }
      setV(cx, 14, cz, stoneStairs);
    }
  }

  // Column 4: Intact Right Colonnade (X=47..48, Z=3..4)
  for (let cx = 47; cx <= 48; cx++) {
    for (let cz = 3; cz <= 4; cz++) {
      for (let y = 6; y <= 12; y++) {
        setV(cx, y, cz, stonePri);
      }
      setV(cx, 13, cz, stoneStairs);
    }
  }
  setV(47, 14, 3, stoneWall);
  setV(47, 15, 3, SEA_LANTERN);

  // Harbor Water Steps (descending into the bay)
  for (let step = 0; step <= 4; step++) {
    const sy = 5 - step;
    const sz = 7 + Math.floor(step / 2);
    for (let sx = 4; sx <= 7; sx++) {
      setV(sx, sy, sz, stonePri);
    }
    for (let sx = 49; sx <= 52; sx++) {
      setV(sx, sy, sz, stonePri);
    }
  }

  // Wooden Harbor Pilings & Wharves
  const pilings = [
    [4, 8],
    [12, 8],
    [44, 8],
    [52, 8],
  ];
  for (const [px, pz] of pilings) {
    for (let y = 1; y <= 6; y++) {
      setV(px, y, pz, woodLog);
    }
    setV(px, 7, pz, woodFence);
  }

  // ==========================================
  // 4. TERRAIN CONFORMANCE (Rule 5 & 6)
  // ==========================================
  // Find lowest occupied voxel for each (x, z) column
  const minYPerCol = new Int32Array(W * D).fill(999);
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      for (let y = 0; y < H; y++) {
        if (getV(x, y, z)) {
          minYPerCol[x * D + z] = y;
          break;
        }
      }
    }
  }

  // Extend foundations downward to meet actual terrain / seabed
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const lowY = minYPerCol[x * D + z];
      if (lowY < 999 && lowY <= 8) {
        const groundH = api.heightAt(x, z);
        const targetH = Math.max(0, Math.min(H - 1, groundH));

        if (targetH < lowY) {
          const isQuay = z <= 8;
          const foundationMat = isQuay ? stonePri : DARK_PRIS;
          for (let y = lowY - 1; y >= targetH; y--) {
            setV(x, y, z, foundationMat);
          }
        }
      }
    }
  }

  // ==========================================
  // 5. EMIT ALL VOXELS DETERMINISTICALLY
  // ==========================================
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[(x * H + y) * D + z];
        if (block) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "behemoth_leviathan",
    seatY: 0,
    anchors: {
      front: [28, 6, 0],
      maw: [28, 24, 6],
      crest: [28, 41, 18],
      quay_left: [8, 6, 3],
      quay_right: [48, 6, 3],
    },
  };
}

