export const envelope = [18, 16, 18];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 4;
  const rng = () => api.random();

  // 3D Voxel Grid Buffer
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      Array(D).fill(null)
    )
  );

  function setBlock(x, y, z, block, overwrite = true) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix < 0 || ix >= W || iy < 0 || iy >= H || iz < 0 || iz >= D) return;
    if (!overwrite && grid[ix][iy][iz] !== null) return;
    grid[ix][iy][iz] = block;
  }

  function getBlock(x, y, z) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix < 0 || ix >= W || iy < 0 || iy >= H || iz < 0 || iz >= D) return null;
    return grid[ix][iy][iz];
  }

  // Math helpers
  function lerp(a, b, t) {
    return a + (b - a) * t;
  }

  function lerp3(p1, p2, t) {
    return [
      lerp(p1[0], p2[0], t),
      lerp(p1[1], p2[1], t),
      lerp(p1[2], p2[2], t)
    ];
  }

  function bezier2(p0, p1, p2, t) {
    const u = 1 - t;
    const tt = t * t;
    const uu = u * u;
    const ut2 = 2 * u * t;
    return [
      uu * p0[0] + ut2 * p1[0] + tt * p2[0],
      uu * p0[1] + ut2 * p1[1] + tt * p2[1],
      uu * p0[2] + ut2 * p1[2] + tt * p2[2]
    ];
  }

  // 3D Geometry primitives
  function drawEllipsoid(cx, cy, cz, rx, ry, rz, blockResolver) {
    const minX = Math.max(0, Math.floor(cx - rx));
    const maxX = Math.min(W - 1, Math.ceil(cx + rx));
    const minY = Math.max(0, Math.floor(cy - ry));
    const maxY = Math.min(H - 1, Math.ceil(cy + ry));
    const minZ = Math.max(0, Math.floor(cz - rz));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rz));

    for (let x = minX; x <= maxX; x++) {
      const qx = (x - cx) / rx;
      const qx2 = qx * qx;
      if (qx2 > 1.0) continue;
      for (let y = minY; y <= maxY; y++) {
        const qy = (y - cy) / ry;
        const qy2 = qy * qy;
        if (qx2 + qy2 > 1.0) continue;
        for (let z = minZ; z <= maxZ; z++) {
          const qz = (z - cz) / rz;
          const d = qx2 + qy2 + qz * qz;
          if (d <= 1.0) {
            const blk = typeof blockResolver === 'function' ? blockResolver(x, y, z, d, qx, qy, qz) : blockResolver;
            if (blk) setBlock(x, y, z, blk);
          }
        }
      }
    }
  }

  function drawBezierTube(p0, p1, p2, r0, r2, blockResolver, numSteps = 24) {
    for (let i = 0; i <= numSteps; i++) {
      const t = i / numSteps;
      const pos = bezier2(p0, p1, p2, t);
      const r = lerp(r0, r2, t);
      const rCeil = Math.ceil(r);
      const minX = Math.max(0, Math.floor(pos[0] - rCeil));
      const maxX = Math.min(W - 1, Math.ceil(pos[0] + rCeil));
      const minY = Math.max(0, Math.floor(pos[1] - rCeil));
      const maxY = Math.min(H - 1, Math.ceil(pos[1] + rCeil));
      const minZ = Math.max(0, Math.floor(pos[2] - rCeil));
      const maxZ = Math.min(D - 1, Math.ceil(pos[2] + rCeil));
      const rSq = r * r;

      for (let x = minX; x <= maxX; x++) {
        const dx = x - pos[0];
        const dx2 = dx * dx;
        if (dx2 > rSq) continue;
        for (let y = minY; y <= maxY; y++) {
          const dy = y - pos[1];
          const dy2 = dy * dy;
          if (dx2 + dy2 > rSq) continue;
          for (let z = minZ; z <= maxZ; z++) {
            const dz = z - pos[2];
            const dSq = dx2 + dy2 + dz * dz;
            if (dSq <= rSq) {
              const blk = typeof blockResolver === 'function' ? blockResolver(x, y, z, Math.sqrt(dSq) / r, t) : blockResolver;
              if (blk) setBlock(x, y, z, blk);
            }
          }
        }
      }
    }
  }

  function drawCylinder(p0, p1, r0, r1, blockResolver, steps = 16) {
    for (let i = 0; i <= steps; i++) {
      const t = i / steps;
      const pos = lerp3(p0, p1, t);
      const r = lerp(r0, r1, t);
      const rCeil = Math.ceil(r);
      const minX = Math.max(0, Math.floor(pos[0] - rCeil));
      const maxX = Math.min(W - 1, Math.ceil(pos[0] + rCeil));
      const minY = Math.max(0, Math.floor(pos[1] - rCeil));
      const maxY = Math.min(H - 1, Math.ceil(pos[1] + rCeil));
      const minZ = Math.max(0, Math.floor(pos[2] - rCeil));
      const maxZ = Math.min(D - 1, Math.ceil(pos[2] + rCeil));
      const rSq = r * r;

      for (let x = minX; x <= maxX; x++) {
        const dx = x - pos[0];
        const dx2 = dx * dx;
        if (dx2 > rSq) continue;
        for (let y = minY; y <= maxY; y++) {
          const dy = y - pos[1];
          const dy2 = dy * dy;
          if (dx2 + dy2 > rSq) continue;
          for (let z = minZ; z <= maxZ; z++) {
            const dz = z - pos[2];
            if (dx2 + dy2 + dz * dz <= rSq) {
              const blk = typeof blockResolver === 'function' ? blockResolver(x, y, z, t) : blockResolver;
              if (blk) setBlock(x, y, z, blk);
            }
          }
        }
      }
    }
  }

  // Instance Variations (N = 12 different sea monsters)
  const instIdx = api.instance.index;
  const paletteType = (instIdx + Math.floor(rng() * 2)) % 4;
  const poseType = (instIdx * 3 + Math.floor(rng() * 2)) % 4;
  const headFeature = (instIdx * 2 + Math.floor(rng() * 2)) % 4;
  const limbMode = (instIdx + Math.floor(rng() * 3)) % 4;
  const tailType = (instIdx * 2 + 1) % 3;

  // Sea Monster Biome Palettes
  const palettes = [
    { // Abyssal Sculk & Dark Prismarine
      primary: "minecraft:dark_prismarine",
      secondary: "minecraft:sculk",
      belly: "minecraft:prismarine_bricks",
      glow: "minecraft:sea_lantern",
      bone: "minecraft:bone_block",
      spineWall: "minecraft:prismarine_wall",
      claw: "minecraft:polished_blackstone",
      clawStair: "minecraft:polished_blackstone_brick_stairs[facing=north,half=bottom]"
    },
    { // Verdant Trench Fiend
      primary: "minecraft:prismarine_bricks",
      secondary: "minecraft:dark_prismarine",
      belly: "minecraft:prismarine",
      glow: "minecraft:verdant_froglight",
      bone: "minecraft:dripstone_block",
      spineWall: "minecraft:prismarine_wall",
      claw: "minecraft:deepslate_tiles",
      clawStair: "minecraft:deepslate_tile_stairs[facing=north,half=bottom]"
    },
    { // Volcanic Deep Lurker
      primary: "minecraft:dark_prismarine",
      secondary: "minecraft:crying_obsidian",
      belly: "minecraft:warped_hyphae",
      glow: "minecraft:ochre_froglight",
      bone: "minecraft:bone_block",
      spineWall: "minecraft:prismarine_wall",
      claw: "minecraft:polished_blackstone",
      clawStair: "minecraft:polished_blackstone_brick_stairs[facing=north,half=bottom]"
    },
    { // Phosphor Leviathan
      primary: "minecraft:prismarine",
      secondary: "minecraft:prismarine_bricks",
      belly: "minecraft:warped_planks",
      glow: "minecraft:pearlescent_froglight",
      bone: "minecraft:bone_block",
      spineWall: "minecraft:prismarine_wall",
      claw: "minecraft:dark_prismarine",
      clawStair: "minecraft:dark_prismarine_stairs[facing=north,half=bottom]"
    }
  ];

  const pal = palettes[paletteType];

  // Base Morphological Spine
  const midX = 8.5 + (rng() - 0.5) * 1.2;

  let headPos, neckPos, chestPos, abdPos, pelvisPos;

  if (poseType === 0) {
    // High Rearing Striker
    headPos = [midX, 11.5 + rng() * 0.8, 2.6];
    neckPos = [midX, 9.8, 4.6];
    chestPos = [midX, 7.8, 7.4];
    abdPos = [midX, 6.8, 10.6];
    pelvisPos = [midX, 6.2, 13.4];
  } else if (poseType === 1) {
    // Low Predatory Stalker
    headPos = [midX, 6.8 + rng() * 0.6, 2.0];
    neckPos = [midX, 6.6, 4.2];
    chestPos = [midX, 6.5, 7.2];
    abdPos = [midX, 6.2, 10.5];
    pelvisPos = [midX, 5.8, 13.5];
  } else if (poseType === 2) {
    // Serpentine S-Curve Strike
    const sCurv = (rng() > 0.5 ? 1 : -1) * 1.8;
    headPos = [midX - sCurv, 9.5 + rng() * 0.8, 2.2];
    neckPos = [midX - sCurv * 0.5, 8.5, 4.5];
    chestPos = [midX + sCurv * 0.6, 7.5, 7.5];
    abdPos = [midX - sCurv * 0.4, 6.8, 10.8];
    pelvisPos = [midX + sCurv * 0.8, 6.0, 13.5];
  } else {
    // Bulky Heavy Behemoth
    headPos = [midX, 8.5 + rng() * 0.8, 2.4];
    neckPos = [midX, 8.0, 4.6];
    chestPos = [midX, 7.6, 7.5];
    abdPos = [midX, 7.0, 10.5];
    pelvisPos = [midX, 6.4, 13.2];
  }

  // Torso Shader
  function bodyBlockResolver(x, y, z, d, qx, qy, qz) {
    if (qy > 0.25) {
      if (Math.abs(x - midX) <= 0.8) {
        return pal.secondary;
      }
      return pal.primary;
    }
    if (Math.abs(qy) <= 0.25 && Math.abs(qx) > 0.55) {
      if ((Math.floor(x) + Math.floor(z)) % 3 === 0) {
        return pal.glow;
      }
      return pal.belly;
    }
    return pal.belly;
  }

  // 1. Build Main Body Segments
  drawEllipsoid(chestPos[0], chestPos[1], chestPos[2], 3.4, 2.5, 3.0, bodyBlockResolver);
  drawEllipsoid(abdPos[0], abdPos[1], abdPos[2], 2.9, 2.3, 2.7, bodyBlockResolver);
  drawEllipsoid(pelvisPos[0], pelvisPos[1], pelvisPos[2], 2.6, 2.0, 2.5, bodyBlockResolver);

  // Connect body segments smoothly
  drawBezierTube(chestPos, abdPos, pelvisPos, 2.8, 2.2, bodyBlockResolver, 16);
  drawBezierTube(chestPos, neckPos, headPos, 2.4, 1.6, bodyBlockResolver, 16);

  // 2. Head & Jaws (Facing North -Z)
  const hx = headPos[0];
  const hy = headPos[1];
  const hz = headPos[2];

  // Upper Cranium & Snout
  drawEllipsoid(hx, hy + 0.4, hz - 0.2, 2.0, 1.3, 1.8, (x, y, z, d, qx, qy) => {
    return qy > 0.1 ? pal.primary : pal.belly;
  });
  drawEllipsoid(hx, hy + 0.2, hz - 1.5, 1.4, 0.9, 1.2, (x, y, z, d, qx, qy) => {
    return qy > 0.1 ? pal.primary : pal.belly;
  });

  // Glowing Eyes
  setBlock(hx - 1.6, hy + 0.6, hz - 0.6, pal.glow);
  setBlock(hx + 1.6, hy + 0.6, hz - 0.6, pal.glow);
  // Brow Ridges
  setBlock(hx - 1.6, hy + 1.2, hz - 0.6, pal.secondary);
  setBlock(hx + 1.6, hy + 1.2, hz - 0.6, pal.secondary);

  // Upper Fangs / Teeth
  setBlock(hx - 0.9, hy - 0.4, hz - 1.3, pal.bone);
  setBlock(hx + 0.9, hy - 0.4, hz - 1.3, pal.bone);
  setBlock(hx - 0.5, hy - 0.4, hz - 2.0, pal.bone);
  setBlock(hx + 0.5, hy - 0.4, hz - 2.0, pal.bone);

  // Gaping Roaring Lower Jaw
  const jawGape = 1.4 + rng() * 1.0;
  const jawHinge = [hx, hy - 0.5, hz + 0.2];
  const jawTip = [hx, hy - jawGape, hz - 1.8];
  drawCylinder(jawHinge, jawTip, 1.2, 0.8, pal.primary, 10);

  // Lower Jaw Teeth
  setBlock(hx - 0.8, hy - jawGape + 0.8, hz - 1.4, pal.bone);
  setBlock(hx + 0.8, hy - jawGape + 0.8, hz - 1.4, pal.bone);
  setBlock(hx, hy - jawGape + 0.7, hz - 1.7, pal.bone);

  // Glowing Abyssal Throat Interior
  setBlock(hx, hy - 0.3, hz - 0.1, pal.glow);

  // Head Features
  if (headFeature === 0) {
    // Bioluminescent Angler Lure
    const lureP0 = [hx, hy + 1.4, hz - 0.5];
    const lureP1 = [hx, hy + 3.4, hz - 1.6];
    const lureP2 = [hx, hy + 2.0, hz - 2.8];
    drawBezierTube(lureP0, lureP1, lureP2, 0.6, 0.4, pal.spineWall, 12);
    setBlock(lureP2[0], lureP2[1], lureP2[2], pal.glow);
    setBlock(lureP2[0], lureP2[1] + 1, lureP2[2], pal.primary);
  } else if (headFeature === 1) {
    // Twin Sweeping Abyssal Horns
    const leftH0 = [hx - 1.2, hy + 1.1, hz];
    const leftH1 = [hx - 2.8, hy + 2.8, hz + 1.2];
    const leftH2 = [hx - 3.2, hy + 2.0, hz + 2.8];
    drawBezierTube(leftH0, leftH1, leftH2, 0.8, 0.3, pal.bone, 12);

    const rightH0 = [hx + 1.2, hy + 1.1, hz];
    const rightH1 = [hx + 2.8, hy + 2.8, hz + 1.2];
    const rightH2 = [hx + 3.2, hy + 2.0, hz + 2.8];
    drawBezierTube(rightH0, rightH1, rightH2, 0.8, 0.3, pal.bone, 12);
  } else if (headFeature === 2) {
    // Spined Dragon Frill / Crest
    for (let angle = -70; angle <= 70; angle += 25) {
      const rad = (angle * Math.PI) / 180;
      const frX = hx + Math.sin(rad) * 2.8;
      const frY = hy + 1.2 + Math.cos(rad) * 2.2;
      drawCylinder([hx, hy + 0.8, hz + 0.5], [frX, frY, hz + 0.8], 0.6, 0.3, pal.primary, 6);
      setBlock(frX, frY, hz + 0.8, pal.spineWall);
    }
  } else {
    // Saber Tusks and Triple Crown
    setBlock(hx - 1.2, hy - jawGape + 1.2, hz - 2.0, pal.bone);
    setBlock(hx - 1.2, hy - jawGape + 1.8, hz - 2.2, pal.bone);
    setBlock(hx + 1.2, hy - jawGape + 1.2, hz - 2.0, pal.bone);
    setBlock(hx + 1.2, hy - jawGape + 1.8, hz - 2.2, pal.bone);

    setBlock(hx - 0.8, hy + 1.5, hz, pal.spineWall);
    setBlock(hx, hy + 1.8, hz, pal.spineWall);
    setBlock(hx + 0.8, hy + 1.5, hz, pal.spineWall);
  }

  // 3. Multi-Limbed Locomotion & Terrain Adaptation
  function buildLimb(shX, shY, shZ, targetX, targetZ, legThickness = 1.3, isFrontScythe = false) {
    const fx = Math.round(Math.max(1, Math.min(W - 2, targetX)));
    const fz = Math.round(Math.max(1, Math.min(D - 2, targetZ)));

    // Ground Height Sampling (Rule 6)
    const gh = api.heightAt(fx, fz);
    const footY = Math.max(0, Math.min(H - 2, seatY + gh));

    const shoulder = [shX, shY, shZ];
    const foot = [fx, footY, fz];

    // Knee joint reaches high and outward for predatory stance
    const outSign = fx >= midX ? 1 : -1;
    const kneeX = (shX + fx) / 2 + outSign * (1.2 + rng() * 0.8);
    const kneeZ = (shZ + fz) / 2 - (isFrontScythe ? 1.0 : 0.0);
    const kneeY = Math.min(H - 2, Math.max(shY, footY) + 1.6 + rng() * 0.8);
    const knee = [kneeX, kneeY, kneeZ];

    // Draw Upper & Lower Leg Tubes
    drawBezierTube(shoulder, knee, foot, legThickness, legThickness * 0.75, (x, y, z, d, t) => {
      return t < 0.3 ? pal.primary : pal.secondary;
    }, 14);

    // Foot Base
    drawEllipsoid(fx, footY + 0.3, fz, 1.4, 0.6, 1.4, pal.claw);

    // Hooked Raptor Claws (3 spreading talons)
    const forwardZ = isFrontScythe ? -1 : (fz < 9 ? -1 : 1);
    setBlock(fx, footY, fz + forwardZ * 1.5, pal.clawStair);
    setBlock(fx - outSign * 1.2, footY, fz + forwardZ * 1.0, pal.clawStair);
    setBlock(fx + outSign * 1.2, footY, fz + forwardZ * 1.0, pal.clawStair);

    // Foundation Skirt to Seafloor/Ground (Rule 6)
    for (let dx = -2; dx <= 2; dx++) {
      for (let dz = -2; dz <= 2; dz++) {
        const cx = fx + dx;
        const cz = fz + dz;
        if (cx < 0 || cx >= W || cz < 0 || cz >= D) continue;

        let topSolidY = -1;
        for (let y = Math.min(H - 1, footY + 2); y >= 0; y--) {
          if (grid[cx][y][cz] !== null) {
            topSolidY = y;
            break;
          }
        }
        if (topSolidY >= 0) {
          const colGroundY = Math.max(0, Math.min(H - 1, seatY + api.heightAt(cx, cz)));
          for (let y = topSolidY - 1; y >= colGroundY; y--) {
            if (grid[cx][y][cz] === null) {
              grid[cx][y][cz] = pal.primary;
            }
          }
        }
      }
    }
  }

  // Generate Limbs based on Limb Configuration
  if (limbMode === 0) {
    // 6 Sprawling Amphibious Limbs (3 Pairs)
    // Front pair
    buildLimb(chestPos[0] - 2.8, chestPos[1] - 0.2, chestPos[2] - 0.8, midX - 5.5, 3.5, 1.4);
    buildLimb(chestPos[0] + 2.8, chestPos[1] - 0.2, chestPos[2] - 0.8, midX + 5.5, 3.5, 1.4);
    // Mid pair
    buildLimb(abdPos[0] - 2.6, abdPos[1] - 0.4, abdPos[2], midX - 6.0, 8.5, 1.3);
    buildLimb(abdPos[0] + 2.6, abdPos[1] - 0.4, abdPos[2], midX + 6.0, 8.5, 1.3);
    // Rear pair
    buildLimb(pelvisPos[0] - 2.4, pelvisPos[1] - 0.2, pelvisPos[2] + 0.6, midX - 5.0, 14.5, 1.4);
    buildLimb(pelvisPos[0] + 2.4, pelvisPos[1] - 0.2, pelvisPos[2] + 0.6, midX + 5.0, 14.5, 1.4);
  } else if (limbMode === 1) {
    // 4 Massive Pillar Legs (Bulky Quadruped)
    // Heavy Front pair
    buildLimb(chestPos[0] - 3.2, chestPos[1], chestPos[2] - 0.4, midX - 4.8, 4.5, 1.7);
    buildLimb(chestPos[0] + 3.2, chestPos[1], chestPos[2] - 0.4, midX + 4.8, 4.5, 1.7);
    // Heavy Rear pair
    buildLimb(pelvisPos[0] - 3.0, pelvisPos[1], pelvisPos[2] + 0.4, midX - 4.8, 13.8, 1.7);
    buildLimb(pelvisPos[0] + 3.0, pelvisPos[1], pelvisPos[2] + 0.4, midX + 4.8, 13.8, 1.7);
  } else if (limbMode === 2) {
    // 4 Crawling Rear Legs + 2 Forward Mantis Scythe Arms
    // Forward Crusher Scythes
    buildLimb(chestPos[0] - 3.0, chestPos[1] + 0.5, chestPos[2] - 1.2, midX - 4.0, 1.8, 1.5, true);
    buildLimb(chestPos[0] + 3.0, chestPos[1] + 0.5, chestPos[2] - 1.2, midX + 4.0, 1.8, 1.5, true);
    // Mid support legs
    buildLimb(abdPos[0] - 2.6, abdPos[1] - 0.4, abdPos[2], midX - 5.8, 7.8, 1.3);
    buildLimb(abdPos[0] + 2.6, abdPos[1] - 0.4, abdPos[2], midX + 5.8, 7.8, 1.3);
    // Rear pushing legs
    buildLimb(pelvisPos[0] - 2.5, pelvisPos[1] - 0.2, pelvisPos[2] + 0.6, midX - 5.2, 14.2, 1.4);
    buildLimb(pelvisPos[0] + 2.5, pelvisPos[1] - 0.2, pelvisPos[2] + 0.6, midX + 5.2, 14.2, 1.4);
  } else {
    // 8 Abyssal Hydra Limbs (4 Pairs)
    for (let p = 0; p < 4; p++) {
      const t = p / 3;
      const shPos = lerp3(chestPos, pelvisPos, t);
      const targetZ = 3.5 + p * 3.6 + (rng() - 0.5) * 0.8;
      const spreadX = 5.2 + Math.sin(t * Math.PI) * 1.2;
      buildLimb(shPos[0] - 2.4, shPos[1] - 0.4, shPos[2], midX - spreadX, targetZ, 1.15);
      buildLimb(shPos[0] + 2.4, shPos[1] - 0.4, shPos[2], midX + spreadX, targetZ, 1.15);
    }
  }

  // 4. Dorsal Fin & Spines
  for (let z = 4; z <= 15; z++) {
    const x = Math.round(midX);
    let topY = -1;
    for (let y = H - 1; y >= 0; y--) {
      if (grid[x][y][z] !== null) {
        topY = y;
        break;
      }
    }
    if (topY >= 0 && topY < H - 2) {
      const spineHt = (z >= 6 && z <= 10) ? (2 + Math.floor(rng() * 2)) : 1;
      for (let s = 1; s <= spineHt; s++) {
        setBlock(x, topY + s, z, pal.spineWall);
      }
      if (z % 3 === 0 && topY + spineHt + 1 < H) {
        setBlock(x, topY + spineHt, z, pal.glow);
      }
    }
  }

  // 5. Tail Appendages
  const tailBase = [pelvisPos[0], pelvisPos[1], pelvisPos[2]];
  if (tailType === 0) {
    // Massive Sinuous Fluke Tail
    const tailSwing = (rng() - 0.5) * 3.5;
    const t1 = [pelvisPos[0] + tailSwing * 0.5, pelvisPos[1] + 0.2, 15.0];
    const t2 = [pelvisPos[0] + tailSwing, pelvisPos[1] + 0.6, 16.8];
    drawBezierTube(tailBase, t1, t2, 2.0, 0.8, pal.primary, 14);

    // Vertical fin blade on tail
    for (let tz = 14; tz <= 16; tz++) {
      const tx = Math.round(lerp(tailBase[0], t2[0], (tz - 13) / 3.8));
      const ty = Math.round(lerp(tailBase[1], t2[1], (tz - 13) / 3.8));
      setBlock(tx, ty + 1, tz, pal.spineWall);
      setBlock(tx, ty + 2, tz, pal.spineWall);
    }
  } else if (tailType === 1) {
    // Bifurcated Twin Whip Tails
    const leftT1 = [pelvisPos[0] - 2.0, pelvisPos[1] + 0.2, 15.0];
    const leftT2 = [pelvisPos[0] - 3.8, pelvisPos[1] + 0.8, 16.8];
    drawBezierTube(tailBase, leftT1, leftT2, 1.6, 0.5, pal.primary, 12);
    setBlock(leftT2[0], leftT2[1], leftT2[2], pal.bone);

    const rightT1 = [pelvisPos[0] + 2.0, pelvisPos[1] + 0.2, 15.0];
    const rightT2 = [pelvisPos[0] + 3.8, pelvisPos[1] + 0.8, 16.8];
    drawBezierTube(tailBase, rightT1, rightT2, 1.6, 0.5, pal.primary, 12);
    setBlock(rightT2[0], rightT2[1], rightT2[2], pal.bone);
  } else {
    // Spiked Club / Thagomizer
    const tEnd = [pelvisPos[0], pelvisPos[1] + 0.2, 15.5];
    drawCylinder(tailBase, tEnd, 1.8, 1.2, pal.primary, 8);
    drawEllipsoid(tEnd[0], tEnd[1], tEnd[2], 1.6, 1.4, 1.6, pal.claw);

    // Radiating Bone Spikes
    setBlock(tEnd[0] - 1.8, tEnd[1], tEnd[2], pal.bone);
    setBlock(tEnd[0] + 1.8, tEnd[1], tEnd[2], pal.bone);
    setBlock(tEnd[0], tEnd[1] + 1.8, tEnd[2], pal.bone);
    setBlock(tEnd[0], tEnd[1], tEnd[2] + 1.8, pal.bone);
  }

  // 6. Underbelly Ground Conformance Pass (Rule 6)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const groundY = Math.max(0, Math.min(H - 1, seatY + api.heightAt(x, z)));
      let lowestY = -1;
      for (let y = 0; y < H; y++) {
        if (grid[x][y][z] !== null) {
          lowestY = y;
          break;
        }
      }
      // If a body or tail voxel is hovering within 2 blocks above ground, extend down
      if (lowestY >= 0 && lowestY > groundY && lowestY - groundY <= 2) {
        for (let y = lowestY - 1; y >= groundY; y--) {
          if (grid[x][y][z] === null) {
            grid[x][y][z] = pal.belly;
          }
        }
      }
    }
  }

  // 7. Single Connected Component Verification & Pruning (Rule 9)
  const visited = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      Array(D).fill(false)
    )
  );

  const components = [];

  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] !== null && !visited[x][y][z]) {
          const comp = [];
          const queue = [[x, y, z]];
          visited[x][y][z] = true;

          while (queue.length > 0) {
            const [cx, cy, cz] = queue.pop();
            comp.push([cx, cy, cz]);

            const neighbors = [
              [cx + 1, cy, cz], [cx - 1, cy, cz],
              [cx, cy + 1, cz], [cx, cy - 1, cz],
              [cx, cy, cz + 1], [cx, cy, cz - 1]
            ];

            for (let n = 0; n < 6; n++) {
              const [nx, ny, nz] = neighbors[n];
              if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
                if (grid[nx][ny][nz] !== null && !visited[nx][ny][nz]) {
                  visited[nx][ny][nz] = true;
                  queue.push([nx, ny, nz]);
                }
              }
            }
          }
          components.push(comp);
        }
      }
    }
  }

  // Keep largest component, prune disconnected strays
  if (components.length > 1) {
    components.sort((a, b) => b.length - a.length);
    for (let c = 1; c < components.length; c++) {
      const comp = components[c];
      for (let v = 0; v < comp.length; v++) {
        const [vx, vy, vz] = comp[v];
        grid[vx][vy][vz] = null;
      }
    }
  }

  // 8. Commit Buffer to Minecraft World
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const blk = grid[x][y][z];
        if (blk !== null) {
          api.set(x, y, z, blk);
        }
      }
    }
  }

  // Result with North-Facing Front Anchor (Rule 12)
  return {
    name: "amphibious_beast",
    seatY: seatY,
    anchors: {
      front: [
        Math.round(headPos[0]),
        Math.max(0, Math.min(H - 1, Math.round(headPos[1]))),
        0
      ]
    }
  };
}
